rule.definition:
a!localVariables(
  local!buTotalResourcesData: #"_a-0000e6bc-0703-8000-9bf8-011c48011c48_3461738"(
    fiscalYear: ri!fiscalYear,
    /*origRegion: if(ri!region = cons!CAW_INT_LABEL_WEST_ASK_REGION_ID,"West","East"),*/
    origBU: ri!bu,
    isActive: true,
    notCancelled: true,
    columns: {"statusId","subPositionTypeId"}
  ).data,
  /*local!buTotalResourcesData*/
  #"SYSTEM_SYSRULES_forEach"(
    items: ri!subPositions,
    expression: a!localVariables(
      local!confirmedIndex: wherecontains(
        #"_a-0000e72d-09a6-8000-9c0e-011c48011c48_5076350",
        tointeger(index(local!buTotalResourcesData,"statusId",{}))
      ),
      local!buConfirmed: index(
        local!buTotalResourcesData,
        local!confirmedIndex
      ),
      local!buInProcess: remove(
        local!buTotalResourcesData,
        local!confirmedIndex
      ),
      a!map(
        subPosition: fv!item.subPosition,
        confirmed: count(index(
          local!buConfirmed,
          wherecontains(
            fv!item.subPositionId,
            tointeger(index(local!buConfirmed,"subPositionTypeId",{}))
          ),
          {}
        )),
        inProcess: count(index(
          local!buInProcess,
          wherecontains(
            fv!item.subPositionId,
            tointeger(index(local!buInProcess,"subPositionTypeId",{}))
          ),
          {}
        ))
      )
    )
  )
)
